const errors = [];
const warns = [];
const err = (m) => errors.push(m);
const warn = (m) => warns.push(m);
// ...checks...
for (const m of errors) console.log(`ERROR  ${m}`);

// Scenes must be contiguous: no gaps, no overlaps, and they fill the whole duration.
if (i === 0 && s.startSec !== 0) err(`${at}: the first scene must start at 0`);
if (i > 0 && s.startSec !== scenes[i - 1].endSec) err(`${at}: startSec must equal the previous endSec`);
if (i === scenes.length - 1 && s.endSec !== doc.durationSec) err(`${at}: the last scene must end at durationSec`);

// Structure.

// Film every scene first, the hook LAST — by then you're warmed up.
const order = [...doc.scenes.keys()].filter((i) => doc.scenes[i].role !== 'hook');
const hookIdx = doc.scenes.findIndex((s) => s.role === 'hook');
if (hookIdx !== -1) order.push(hookIdx);

